    t = Builder()
    t.h('Kanz al-Daqa\'iq', 'کنز الدقائق', 'کنز الدقائق')
    t.p('This is a book of Hanafi fiqh, and it is the compilation of Imam Hafiz al-Din al-Nasafi.', 'یہ فقہ حنفی کتاب ہے اور امام حافظ الدین النسفی کی تالیف ہے۔', 'دا د حنفي فقه کتاب دی، او د امام حافظ الدین النسفي تالیف دی.')
